/* * @lc app=leetcode id=2095 lang=kotlin * * [2095] Delete the Middle Node of a Linked List */ class Solution { fun deleteMiddle(head: ListNode?): ListNode? = head?.next?.let { h -> head.apply { generateSequence(Pair(this, next?.next)) { (slow, fast) -> if (fast != null && fast.next != null) Pair(slow.next!!, fast.next?.next) else null }.last().let { (slow, _) -> slow.next = slow.next?.next } } } }